    q11_6: { l: "Equipment and space available", o: { phone: "Recent smartphone", camera: "Camera", mic: "Microphone", lights: "Lights", teleprompter: "Teleprompter", office: "A nice office space", studio: "A studio" } },
    q11_7: { l: "Your monthly content budget (team, editing, ads)" },
    q11_8: { l: "Who approves content before it's posted?", o: { me24: "Me, within 24h", me72: "Me, within 2–3 days", team: "Someone on my team", none: "No approval needed" } },
    q11_9: { l: "Upcoming periods when you'll be less available", ph: "Ramadan (I'll film less), August in the North with family, a trade fair in Paris in March." },

    q12_1: { l: "Your current accounts", h: "Fill in only the platforms you have.", cols: { handle: { l: "Account", ph: "@youssef.elamrani" }, followers: { l: "Followers", ph: "2,400" }, status: { l: "Status", o: { active: "Active", rarely: "Rarely", inactive: "Inactive" } } } },
    q12_2: { l: "What have you posted so far, and how did it perform?", h: "Paste the link to your best post and tell me why you think it worked.", ph: "Mostly company news and event photos. Best post: a video explaining why I let go of my biggest client — 85k views. I think it worked because it was honest." },
    q12_3: { l: "What did you try and stop — and why?", ph: "I posted daily for 2 months in 2023, then stopped: no results, no time, and the agency's videos didn't feel like me." },
    q12_4: { l: "Existing assets we can use", o: { press: "Press articles", podcasts: "Podcast appearances", talks: "Talks & conferences", photos: "Professional photos", archive: "Archive of old videos & photos", awards: "Awards", book: "A book or articles I wrote" }, dph: "TEDx Casablanca talk in 2022 (video available), 2 articles in L'Économiste." },
    q12_5: { l: "Would you put ad money behind your content?", o: { yes: "Yes", test: "Yes, to test", no: "No — organic only" } },

    q13_1: { l: "Your targets over time", h: "Rough numbers are fine. Leave blank what doesn't apply.", cols: { m3: { l: "3 months", ph: "5k" }, m6: { l: "6 months", ph: "15k" }, m12: { l: "12 months", ph: "50k" } } },
    q13_2: { l: "Your main platform to focus on" },
    q13_3: { l: "If only ONE number mattered, which would it be?" },
    q13_4: { l: "Revenue you'd like the brand to influence in 12 months", ph: "2,000,000" },

    q14_1: { l: "What does success mean to you in 12 months — beyond the numbers?", ph: "Being invited to speak where my clients are. My team being proud to work here. My father telling me he saw my video." },
    q14_2: { l: "What would make you quit? And how would you react if results were slow at 6 months?", ph: "If it takes more than 4 hours a week, I'll drop it. If results are slow but I see progress, I'll continue — I just need to understand why." },
    q14_3a: { l: "How committed are you to this project?", lo: "Just curious", hi: "All in" },
    q14_3b: { l: "What could get in the way?", ph: "Operational crises, travel, and my own perfectionism." },
    q14_4: { l: "How do you want to work with me?", o: { together: "We build it together — I want to learn", dfy: "Done for me — I just show up and film", unsure: "Not sure yet" } },
    q14_5: { l: "How often would you like to check in?", o: { weekly: "Weekly call", biweekly: "Call every 2 weeks", monthly: "Monthly call", async: "WhatsApp updates, calls when needed" } },
