    q0_3: { l: "Comment vous joindre ?", f: { whatsapp: { l: "Numéro WhatsApp", ph: "+212 6 12 34 56 78" }, email: { l: "E-mail", ph: "youssef@atlaslogistics.ma" } } },
    q0_4: { l: "Dans quelle ville et quel pays vivez-vous ?", ph: "Casablanca, Maroc" },
