    q1_1: { l: "قدّم نفسك في جملتين أو ثلاث، كما تفعل مع شخص لا يعرفك في عشاء عمل.", ph: "أدير شركة لوجيستيك توصّل الطلبيات لأكثر من 300 علامة تجارة إلكترونية في المغرب. بدأت بسيارة نقل واحدة في درب السلطان سنة 2014، واليوم نحن 120 شخصًا." },
    q1_2: { l: "احكِ لي مسارك: من أين بدأت، وما المراحل الكبرى حتى اليوم؟", h: "لا تجمّله. الأماكن، الوظائف، الإخفاقات، النجاحات: القصة الحقيقية.", ph: "نشأت في فاس، وكان والدي تاجرًا. درست الهندسة في الرباط، ثم اشتغلت 3 سنوات في شركة فرنسية متعددة الجنسيات، واستقلت في سن 27. أغلقت شركتي الأولى بعد 18 شهرًا. وفي 2014 بدأت من جديد بسيارة نقل واحدة…" },
    q1_3: { l: "ثلاث نقاط تحوّل في حياتك أو مسارك المهني", h: "لكل واحدة: ماذا حدث، ماذا قررت، وما الذي تغيّر بعدها.", f: { title: { l: "نقطة التحول", ph: "خسارة أكبر عميل لدينا سنة 2019" }, story: { l: "ماذا حدث، ماذا قررت، ما الذي تغيّر", ph: "ذهب 60% من رقم معاملاتنا بين ليلة وضحاها. قررت ألا نعتمد على عميل واحد أبدًا: خلال 12 شهرًا وقّعنا مع 40 مقاولة صغيرة ومتوسطة وأصبحنا أكثر ربحية من قبل." } } },
    q1_4: { l: "أصعب لحظة مررت بها أو أكبر إخفاق، وما الذي تعلّمته منه", h: "ستقرّر لاحقًا ما يمكن نشره. هنا، كن صريحًا.", ph: "سنة 2016 لم أستطع دفع الأجور لمدة شهرين. بعت سيارتي لأدفع للفريق. تعلّمت أن السيولة هي الأكسجين، وأن الوفاء يُبنى في الأشهر الصعبة." },
    q1_5: { l: "شيء سيتفاجأ الناس عندما يعرفونه عنك", ph: "كنت لاعب شطرنج على المستوى الوطني في مراهقتي، وما زلت أقرأ كتابًا كل أسبوع، أغلبها في التاريخ." },
    q1_6: { l: "ما الذي يميّزك عن غيرك في مجالك؟", h: "أعطِ مثالًا حقيقيًا، لا شعارًا.", ph: "أغلب الوكالات ترسل تقارير. أما أنا فأجلس مع صاحب الشركة كل يوم إثنين ونراجع السيولة معًا. أحد العملاء انتقل من 80 ألف إلى 400 ألف درهم شهريًا لأننا أوقفنا 3 منتجات كان يحبها لكنها كانت تخسر." },
    q1_7a: { l: "ميزتك التي يصعب تقليدها: ما الذي تملكه ولا يمكن نسخه بسهولة؟", h: "اختر كل ما ينطبق.", o: { results: "نتائج مثبتة", experience: "سنوات من الخبرة", network: "شبكة علاقات", access: "وصول إلى أسواق أو أشخاص أو معلومات", skill: "مهارة نادرة", story: "قصة شخصية قوية", method: "منهجيتي الخاصة", resources: "موارد ورأس مال", languages: "لغات وثقافات" } },
    q1_7b: { l: "اشرح هذه الميزة بكلماتك", h: "لماذا لا يستطيع منافس أن ينسخها ببساطة؟", ph: "تفاوضت شخصيًا مع كل شركات النقل الكبرى في المغرب. أعرف الأسعار الحقيقية، والآجال الحقيقية، ومن أتصل به عندما تتعطل بضاعة في الميناء. لا أحد على مواقع التواصل يملك هذه الرؤية من الداخل." },
