    q1_9: { l: "كيف سيصفك هؤلاء الأشخاص، بثلاث كلمات لكل واحد؟", f: { spouse: { l: "زوجتك أو زوجك", ph: "مثابر، حامٍ، عنيد" }, friend: { l: "أقرب أصدقائك", ph: "وفيّ، مرح، شغوف" }, employee: { l: "أحد موظفيك", ph: "متطلّب، عادل، سريع" } } },

